Definition fresh_in (L0 : list (Z * Z)) (b : Z) : Prop := forall q k, In (q, k) L0 -> b <> q.

Definition glp_inv (L0 L : list (Z * Z)) (m : mem) (ls n : Z) (lps : list Z) (es : list pixe) : Prop :=
  chunk L ls (n * 8) /\ u64arr asegs m ls (map (Z_to_bv 64) lps)
  /\ Forall2 (fun lp e => lines_obj L m lp (pe_v e)) lps es /\ List.NoDup (ls :: lps)
  /\ Forall (fresh_in L0) (ls :: lps) /\ Z.of_nat (length lps) <= n.

Lemma lines_obj_keep : forall L L' (m m' : mem) lp v, lines_obj L m lp v -> (forall x, In x L -> In x L') ->
  keeps_live [(lp, 8 * p_h v)] m m' -> lines_obj L' m' lp v.
